mapper.update:
UPDATE following
SET rel_status = 1, updated_at = NOW(3), created_at = NOW(3)
WHERE from_user_id = #{fromUserId}
  AND to_user_id = #{toUserId}
  AND rel_status = 0

UPDATE following
SET rel_status = 0, updated_at = NOW(3)
WHERE from_user_id = #{fromUserId}
  AND to_user_id = #{toUserId}
  AND rel_status = 1

mapper.select:
SELECT COUNT(1)
FROM following
WHERE from_user_id = #{fromUserId}
  AND to_user_id = #{toUserId}
  AND rel_status = 1

SELECT to_user_id AS userId, created_at AS createdAt
FROM following
WHERE from_user_id = #{fromUserId}
  AND rel_status = 1
ORDER BY created_at DESC, to_user_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT from_user_id AS userId, created_at AS createdAt
FROM following
WHERE to_user_id = #{toUserId}
  AND rel_status = 1
ORDER BY created_at DESC, from_user_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT user_id FROM ( SELECT from_user_id AS user_id FROM following
UNION
SELECT to_user_id AS user_id FROM following ) relation_users ORDER BY user_id LIMIT #{limit}
